#!/usr/bin/env python3
"""Build a public XMLTV guide from provider IDs and curated EPG2/EPG37.
Never publishes stream URLs, credentials, or private playlists.
"""
import csv
import gzip
import io
import os
import re
import urllib.request
import urllib.error
import time
from urllib.parse import urlsplit
import xml.etree.ElementTree as ET
from collections import Counter, defaultdict
from pathlib import Path
from datetime import datetime, timezone, timedelta
from zoneinfo import ZoneInfo

ROOT = Path(__file__).resolve().parent
SOURCES = {'epg2': 'https://raw.githubusercontent.com/ferteque/Curated-M3U-Repository/main/epg2.xml.gz',
           'epg37': 'https://raw.githubusercontent.com/ferteque/Curated-M3U-Repository/main/epg37.xml.gz',
           'epg6': 'https://raw.githubusercontent.com/ferteque/Curated-M3U-Repository/main/epg6.xml.gz'}
MAX_DOWNLOAD = 350 * 1024 * 1024

def norm(s):
    return re.sub(r'[^a-z0-9]', '', (s or '').casefold())

def clean_name(s):
    s = (s or '').upper()
    s = re.sub(r'\b(?:UHD|FHD|HD|SD|HEVC|H265|H264|4K|1080P|720P|50FPS|60FPS)\b', ' ', s)
    s = re.sub(r'^(?:US|USA|UK|CA|CANADA|VIP|LIVE|TV)\s*[:|\-]+\s*', '', s)
    return norm(s)

def download(url):
    """Download a public XMLTV source, without exposing secrets in the logs."""
    url = str(url).strip()
    parsed = urlsplit(url)
    if parsed.scheme in ('', 'file'):
        local = Path(parsed.path if parsed.scheme == 'file' else url)
        if not local.is_absolute():
            local = ROOT / local
        b = local.read_bytes()
    else:
        if parsed.scheme not in ('http', 'https'):
            raise ValueError('Unsupported EPG source URL scheme')
        request = urllib.request.Request(url, headers={
            'User-Agent': 'Mozilla/5.0 (compatible; MyEPG/2.0; +https://github.com)',
            'Accept': 'application/octet-stream, application/gzip, application/xml, */*',
        })
        for attempt in range(3):
            try:
                with urllib.request.urlopen(request, timeout=240) as response:
                    b = response.read(MAX_DOWNLOAD + 1)
                break
            except urllib.error.HTTPError as exc:
                # A 403 normally means denied access, not a transient failure.
                if exc.code not in (408, 429, 500, 502, 503, 504) or attempt == 2:
                    raise
                time.sleep(2 ** attempt)
            except (urllib.error.URLError, TimeoutError):
                if attempt == 2:
                    raise
                time.sleep(2 ** attempt)
    if len(b) > MAX_DOWNLOAD:
        raise RuntimeError('EPG download exceeds safety limit')
    result = gzip.decompress(b) if b[:2] == b'\x1f\x8b' else b
    if not result.lstrip().startswith((b'<?xml', b'<tv', b'\xef\xbb\xbf<?xml')):
        raise RuntimeError('Source is not a valid XMLTV document (possibly an access-denied page)')
    return result


def load_guide(source, default_url):
    """Network first; then optional committed/cached XMLTV source if blocked."""
    custom = os.environ.get(source.upper() + '_URL', '').strip()
    path = custom or default_url
    attempts = [path]
    local_override = os.environ.get(source.upper() + '_FILE', '').strip()
    if local_override:
        attempts.append(local_override)
    attempts.extend((f'sources/{source}.xml.gz', f'sources/{source}.xml',
                     f'{source}.xml.gz', f'{source}.xml'))
    attempted_local = set()
    for entry in attempts:
        parsed = urlsplit(entry)
        is_local = parsed.scheme in ('', 'file')
        if is_local:
            local = Path(parsed.path if parsed.scheme == 'file' else entry)
            if not local.is_absolute():
                local = ROOT / local
            if local in attempted_local or not local.is_file():
                continue
            attempted_local.add(local)
        try:
            raw = download(entry)
            # Validate XML structure before accepting the source.
            with io.BytesIO(raw) as stream:
                root = ET.iterparse(stream, events=('start',))
                _, first = next(root)
                if first.tag.rsplit('}', 1)[-1] != 'tv':
                    raise ValueError('Unexpected XML root (expected tv)')
            print(f'EPG source {source}: loaded from ' +
                  ('local XMLTV file' if is_local else 'remote URL'), flush=True)
            return raw
        except (OSError, ET.ParseError, ValueError, RuntimeError) as exc:
            detail = f'HTTP {exc.code}' if isinstance(exc, urllib.error.HTTPError) else type(exc).__name__
            # Report source/host only: URLs can contain credentials or tokens.
            hostname = parsed.hostname or 'local file'
            print(f'WARNING: {source} source at {hostname} failed: {detail}', flush=True)
    print(f'WARNING: no readable {source} source (configure {source.upper()}_URL '
          f'or commit sources/{source}.xml.gz)', flush=True)
    return None

def rows(path):
    with path.open('r', encoding='utf-8-sig', newline='') as f:
        return list(csv.DictReader(f))

def source_key(s):
    s = (s or '').lower()
    return 'epg6' if 'epg6' in s else ('epg2' if 'epg2' in s else 'epg37')

def clone(el):
    return ET.fromstring(ET.tostring(el, encoding='utf-8'))

def valid_time(value, cutoff):
    try:
        return datetime.strptime(value[:14], '%Y%m%d%H%M%S').replace(tzinfo=timezone.utc) >= cutoff
    except (ValueError, TypeError):
        return False

def flo_number(name):
    """Recognize provider FLO 002 or source FLSP 002, but not event titles."""
    m = re.search(r'\b(?:FLO|FLSP)\s*[-_ ]?\s*(\d{1,4})\b', name or '', re.I)
    return int(m.group(1)) if m else None


def flo_source_index(source_channels):
    """Resolve numbered source labels every run; never assume dummy IDs persist."""
    index = defaultdict(set)
    for (source, cid), channel in source_channels.items():
        if source != 'epg2':
            continue
        for el in channel.findall('display-name'):
            if el.text and re.match(r'^\s*\(?\s*FLSP\s*[-_ ]?\s*\d{1,4}\s*\)?(?:\s|\||$)', el.text, re.I):
                index[flo_number(el.text)].add((source, cid))
    return index


def canonical_names(value):
    """Conservative aliases for broadcast feeds, without fuzzy station guesses."""
    raw = (value or '').upper()
    raw = re.sub(r'^(?:(?:US|USA|UK|CA|CANADA|VIP|LIVE|TV)\s*[:|\-]+\s*)+', '', raw)
    raw = re.sub(r'\b(?:UHD|FHD|HD|SD|HEVC|H265|H264|4K|1080P|720P|50FPS|60FPS)\b', ' ', raw)
    raw = re.sub(r'\b(?:EAST|WEST|PACIFIC)\b', lambda m: ' '+m.group(0)+' ', raw)
    base = norm(raw)
    keys = {base} if len(base) >= 5 else set()
    # Do not erase time-shift, regional, network, or station identifiers.
    stripped = re.sub(r'\b(?:CHANNEL|CH|TELEVISION)\b', ' ', raw)
    alias = norm(stripped)
    if len(alias) >= 5:
        keys.add(alias)
    return keys

def event_number(name, prefixes):
    match = re.search(r'\b(?:' + prefixes + r')\s*[-_ +#]*\s*0*(\d{1,4})\b', name or '', re.I)
    return int(match.group(1)) if match else None

def espn37_numbered_index(source_channels):
    """Match ESPN+ feed numbers exclusively from EPG37, including event labels.

    Accept e.g. 'US - ESPN PLUS 247 :' and 'ESPN+ 001 | event'.
    A feed number is only usable when it resolves to one EPG37 channel ID.
    """
    found = defaultdict(set)
    pattern = re.compile(
        r'\bESPN\s*(?:\+|PLUS)\s*[-_ #]*0*(\d{1,4})\b', re.I)
    for pair, channel in source_channels.items():
        if pair[0] != 'epg37':
            continue
        for label in [pair[1]] + [x.text or '' for x in channel.findall('display-name')]:
            match = pattern.search(label)
            if match and 1 <= int(match.group(1)) <= 600:
                found[int(match.group(1))].add(pair)
    return found


def select_unique(candidates):
    """Prefer EPG37 only if it identifies the same feed in both sources."""
    if not candidates:
        return set()
    if len(candidates) == 1:
        return set(candidates)
    # Multiple source IDs with identical spelling can still be distinct feeds.
    ids = {cid.casefold() for _, cid in candidates}
    if len(ids) == 1:
        return {sorted(candidates, key=lambda x: (x[0] != 'epg37', x[1]))[0]}
    return set(candidates)


EASTERN = ZoneInfo("America/New_York")
def flo_advertised(name):
    m = re.search(r"\bFLO\s*0*\d+\s*[:|]\s*(.*)", name, re.I)
    if not m: return None
    detail = m.group(1)
    t = re.search(r"\b(1[0-2]|0?[1-9]):([0-5]\d)\s*(AM|PM)\s*(?:ET|EST|EDT)\b", detail, re.I)
    if not t: return None
    title = detail[:t.start()].strip(" -–—|:")
    title = re.sub(r"^LIVE\s*[-:|]\s*", "", title, flags=re.I).strip()
    if not title: return None
    h = int(t.group(1)) % 12 + (12 if t.group(3).upper()=="PM" else 0)
    return title,h,int(t.group(2))

def flo_programme(channel, title, start, end, desc):
    def fmt(dt): return dt.astimezone(timezone.utc).strftime("%Y%m%d%H%M%S +0000")
    p = ET.Element("programme", {"channel":channel,"start":fmt(start),"stop":fmt(end)})
    ET.SubElement(p,"title",{"lang":"en"}).text=title
    ET.SubElement(p,"desc",{"lang":"en"}).text=desc
    return p

def flo_custom_schedule(target, provider_name, source_starts, now):
    info = flo_advertised(provider_name)
    if not info: return None
    title,h,minute=info
    # Prefer an EPG2 start date with matching Eastern clock time.
    aligned=[d for d in source_starts if (d.astimezone(EASTERN).hour,d.astimezone(EASTERN).minute)==(h,minute)]
    eligible=[d for d in aligned if d>=now-timedelta(hours=3)]
    if eligible:
        start=min(eligible)
        desc="Start date confirmed by EPG2; 3-hour duration estimated."
    else:
        local=now.astimezone(EASTERN).replace(hour=h,minute=minute,second=0,microsecond=0)
        if local.astimezone(timezone.utc)<now-timedelta(hours=3): local+=timedelta(days=1)
        start=local.astimezone(timezone.utc)
        desc="Date inferred from next Eastern Time occurrence; 3-hour duration estimated."
    end=start+timedelta(hours=3)
    result=[]
    if start>now:
        result.append(flo_programme(target,"Signing Off",now,start,"Check back for scheduled events."))
    result.append(flo_programme(target,title,start,end,desc))
    result.append(flo_programme(target,"Signing Off",end,max(end+timedelta(hours=1),now+timedelta(days=2)),"Check back for scheduled events."))
    return result

def parse_xmltv_start(s):
    m=re.match(r"^(\d{14})(?:\s*([+-]\d{4}))?",s or "")
    if not m: return None
    dt=datetime.strptime(m.group(1),"%Y%m%d%H%M%S")
    offset=m.group(2)
    if offset:
        minutes=(1 if offset[0]=="+" else -1)*(int(offset[1:3])*60+int(offset[3:5]))
        return dt.replace(tzinfo=timezone(timedelta(minutes=minutes))).astimezone(timezone.utc)
    return dt.replace(tzinfo=timezone.utc)


