def companion_entries():
    return json.loads(zlib.decompress(base64.b85decode(PLAYLIST_DIRECTORY_B85)).decode('utf-8'))

SPORTS_LEAGUES = ('NFL', 'NBA', 'NHL', 'AHL', 'MLS', 'MLB', 'NCAA', 'WNBA', 'NCAAF', 'NCAAB')

def league_feed(name):
    """Normalize regional and numbered league feeds, including GAME and zero padding."""
    raw = (name or '').upper()
    raw = re.sub(r'\b(?:UHD|FHD|HD|SD|4K|HEVC|LIVE|EVENTS?)\b', ' ', raw)
    raw = re.sub(r'^(?:(?:US|USA|CA|CANADA|UK|VIP|SPORTS?)\s*[-:|]\s*)+', '', raw)
    m = re.search(r'(?<![A-Z0-9])(' + '|'.join(SPORTS_LEAGUES) + r')\s*(?:GAME|GAMES|FEED|CHANNEL|CH)?\s*[-_#|: ]*0*(\d{1,3})(?!\d)', raw)
    if not m: return None
    region = 'CA' if re.search(r'\b(?:CA|CANADA|CANADIAN)\s*[-:|]', (name or '').upper()) else ('US' if re.search(r'\b(?:US|USA)\s*[-:|]', (name or '').upper()) else '')
    return m.group(1), int(m.group(2)), region

def sports_source_quality(pair, source_channels):
    """Prefer an advertised matchup over generic GAME/Signing Off channel labels."""
    ch = source_channels.get(pair)
    if ch is None: return -1
    names = ' '.join((e.text or '') for e in ch.findall('display-name'))
    score = 0
    if re.search(r'\b(?:VS\.?|VERSUS|AT)\b|\s+@\s+|\b(?:TNF|MNF|SNF)\b|\b\d{1,2}(?::\d{2})?\s*(?:AM|PM)\b', names, re.I): score += 10
    if re.search(r'\b(?:SIGNING OFF|NO EVENT|NO PROGRAM|TO BE ANNOUNCED|TBA)\b', names, re.I): score -= 10
    if pair[0] == 'epg2': score += 1
    return score

def choose_companion(candidates, epgid, source_channels=None, sports=False):
    if len(candidates) == 1: return set(candidates)
    exact = {p for p in candidates if p[1].casefold() == epgid.casefold()} if epgid else set()
    if len(exact)==1: return exact
    if sports and source_channels and candidates:
        ranked = sorted(((sports_source_quality(p, source_channels),p) for p in candidates), reverse=True)
        if len(ranked)==1 or (ranked[0][0] >= 10 and ranked[0][0] > ranked[1][0]):
            return {ranked[0][1]}
    return set()

def allowed_category(group):
    """Accept regional categories and VIP Christmas, not unrelated VIP groups."""
    group = (group or '').strip()
    if re.match(r'^VIP\s*[-|:]\s*CHRISTMAS(?:\b|\s*[-|:])', group, re.I):
        return True
    return bool(re.match(r'^(?:US|AM|UK|CA|VIP)(?=$|[\s|:_-])', group, re.I))


def christmas_display_name(name):
    """Apply the same prefix removal used for 24/7 titles."""
    return re.sub(r'^(?:(?:VIP\s*[-|:]\s*CHRISTMAS|24\s*/\s*7|XMAS)\s*[-|:]?\s*)+', '', name or '', flags=re.I).strip()


def xtream_json(base, username, password, action):
    """Use POST to avoid putting credentials in URL/query strings or logs."""
    from urllib.parse import urlsplit, urlunsplit, urlencode
    base = base.strip().rstrip('/')
    parsed = urlsplit(base)
    if parsed.scheme not in ('http', 'https') or not parsed.netloc or parsed.username or parsed.password:
        raise ValueError('XTREAM_URL must be an http(s) server URL without credentials')
    url = urlunsplit((parsed.scheme, parsed.netloc, parsed.path.rstrip('/') + '/player_api.php', '', ''))
    payload = urlencode({'username': username, 'password': password, 'action': action}).encode()
    request = urllib.request.Request(url, data=payload, headers={'User-Agent': 'My-EPG-v2/2.0', 'Content-Type': 'application/x-www-form-urlencoded'})
    with urllib.request.urlopen(request, timeout=90) as response:
        raw = response.read(45 * 1024 * 1024 + 1)
    if len(raw) > 45 * 1024 * 1024:
        raise RuntimeError('Xtream API response too large')
    result = json.loads(raw)
    if not isinstance(result, (list, dict)):
        raise ValueError('Unexpected Xtream API response')
    return result


def refresh_playlist_catalog():
    """Refresh before any EPG download. Never write provider secrets or stream URLs."""
    url = os.getenv('XTREAM_URL', '').strip()
    user = os.getenv('XTREAM_USERNAME', '').strip()
    password = os.getenv('XTREAM_PASSWORD', '').strip()
    if not any((url, user, password)):
        print('Xtream secrets absent; using filtered existing M3U-derived channels.csv')
        return None
    if not all((url, user, password)):
        raise RuntimeError('Incomplete Xtream configuration: set all three XTREAM secrets')
    categories = xtream_json(url, user, password, 'get_live_categories')
    streams = xtream_json(url, user, password, 'get_live_streams')
    if not isinstance(categories, list) or not isinstance(streams, list):
        raise RuntimeError('Xtream did not return live categories and streams')
    category_names = {str(c.get('category_id')): str(c.get('category_name', '')) for c in categories if isinstance(c, dict)}
    permitted = {cid for cid, name in category_names.items() if allowed_category(name)}
    if not permitted:
        raise RuntimeError('No matching US/AM/UK/CA/VIP Christmas categories returned')
    catalog = []
    for stream in streams:
        if not isinstance(stream, dict):
            continue
        cid = str(stream.get('category_id', ''))
        if cid not in permitted:
            continue
        name = str(stream.get('name') or '').strip()
        if not name or name.startswith('#####'):
            continue
        group = category_names[cid]
        if re.match(r'^VIP\s*[-|:]\s*CHRISTMAS\b', group, re.I):
            name = christmas_display_name(name)
        catalog.append({'Source': 'Xtream', 'Group': group, 'ChannelName': name,
                        'StreamID': str(stream.get('stream_id') or ''),
                        'EPGID': str(stream.get('epg_channel_id') or ''),
                        'TVGName': '', 'ProviderID': '', 'Scope': 'Xtream live'})
    if not catalog:
        raise RuntimeError('Xtream returned no channels in selected categories')
    print('Xtream playlist refreshed before guide build:', len(catalog), 'selected channels')
    return catalog



# Numbered live sports only. Replay feeds are deliberately excluded.
SPORTS_MATCHUP = re.compile(r"([A-Za-z0-9][A-Za-z0-9 .&'/-]{1,65}?)\s+(?:vs\.?|versus|@|at)\s+([A-Za-z0-9][A-Za-z0-9 .&'/-]{1,65})", re.I)
SPORTS_PLACEHOLDER = re.compile(r'^(?:no game(?: today)?|no event(?: today| at this time)?|signing off|upcoming|tba|to be announced|off air|no information|:[A-Z]{2,6}\s*\d+)', re.I)

def sports_live_feed(name):
    if re.search(r'\bREPLAY\s*[-#:]?\s*\d+|\bREPLAYS?\b', name or '', re.I):
        return None
    feed = league_feed(name)
    if not feed:
        return None
    if feed[0] == 'NCAAF' and feed[1] < 17:
        return None
    return feed

def event_teams(name):
    # Require a genuine two-team event; remove channel-number prefix first.
    name = re.sub(r'^.*?\b(?:NBA|NFL|NHL|MLB|MLS|AHL|MILB|NCAAF|NCAAB)\s*(?:GAME|GAMES|FEED|CHANNEL|CH)?\s*[-_#|: ]*\d+\s*[-:|]?\s*', '', name or '', flags=re.I)
    name = re.split(r'\s*\(?:\s*\d{1,2}:\d{2}', name)[0]
    m = SPORTS_MATCHUP.search(name)
    if not m: return None
    a, b = (re.sub(r'\s+', ' ', x).strip(' .-:|') for x in m.groups())
    b = re.sub(r'\s+(?:LIVE|HD|FHD|UHD|4K)\s*$', '', b, flags=re.I).strip()
    if not a or not b or len(a)<2 or len(b)<2: return None
    return a, b

def same_event(a, b):
    return bool(a and b and sorted(norm(x) for x in a) == sorted(norm(x) for x in b))

def event_title(p):
    return ' '.join((x.text or '') for x in p.findall('title')).strip()

def format_upcoming(title, start):
    local = start.astimezone(ZoneInfo('America/New_York'))
    return f'Upcoming "{title}" {local.strftime("%b.")} {local.day} ({local.strftime("%I:%M %p").lstrip("0")} {local.tzname()})'

def make_sports_guide(catalog, channels, programmes, reports):
    """Verify Xtream-advertised matchup against XMLTV event AND start time.

    An arbitrary league schedule cannot determine which provider GAME number
    carries a broadcast. No matching evidence => NO GAME TODAY.
    """
    now = datetime.now(timezone.utc)
    horizon = now + timedelta(days=7)
    by_id = defaultdict(list)
    for p in programmes:
        by_id[p.get('channel','')].append(p)
    by_feed = defaultdict(set)
    for cid, ch in channels.items():
        for n in [cid] + [x.text or '' for x in ch.findall('display-name')]:
            feed = sports_live_feed(n)
            if feed: by_feed[feed[:2]].add(cid)
    by_provider = defaultdict(list)
    for row in catalog:
        pid = (row.get('EPGID') or '').strip()
        name = (row.get('ChannelName') or '').strip()
        feed = sports_live_feed(name)
        if pid and feed and pid in channels:
            by_provider[pid].append((name,feed))
            by_feed[feed[:2]].add(pid)
    replace = {}
    audit = []
    for pid, candidates in by_provider.items():
        # Never reinterpret replay channels or ambiguous conflicting provider names.
        feeds = {x[1][:2] for x in candidates}
        advertised = [(name, event_teams(name)) for name, _ in candidates]
        matches = [teams for _, teams in advertised if teams]
        verified = []
        if len(feeds) == 1 and matches and all(same_event(matches[0], t) for t in matches):
            feed = next(iter(feeds))
            donors = set(by_feed.get(feed, ())) | {pid}
            for donor in donors:
                for p in by_id.get(donor, ()):
                    title = event_title(p)
                    teams = event_teams(title)
                    # Source programme must explicitly identify same two teams.
                    if not teams or not same_event(teams, matches[0]): continue
                    start = parse_xmltv_start(p.get('start',''))
                    stop = parse_xmltv_start(p.get('stop',''))
                    if not start or not stop or stop <= start or stop < now or start > horizon: continue
                    verified.append((start, stop, matches[0]))
        verified.sort(key=lambda x:x[0])
        # Reject overlapping or conflicting schedule records.
        distinct = []
        for ev in verified:
            if not distinct or ev[0] > distinct[-1][0]:
                distinct.append(ev)
        cursor = now
        result = []
        status = 'NO GAME TODAY'
        for start, stop, teams in distinct:
            if stop <= cursor: continue
            event = f'{teams[0]} vs {teams[1]}'
            if cursor < start:
                result.append(flo_programme(pid,format_upcoming(event,start),cursor,start,'Verified matchup and start time from source EPG.'))
            if start < stop:
                result.append(flo_programme(pid,event,max(start,cursor),stop,'Live sports event.'))
            cursor = max(cursor,stop)
            status = 'VERIFIED'
        if cursor < horizon:
            label = 'Signing Off' if distinct else 'NO GAME TODAY'
            result.append(flo_programme(pid,label,cursor,horizon,'No further confirmed event is assigned to this channel.'))
        replace[pid] = result
        audit.append((pid, ' | '.join(n for n,_ in candidates),status,len(distinct)))
    if replace:
        programmes = [p for p in programmes if p.get('channel') not in replace]
        for entries in replace.values(): programmes.extend(entries)
    with (reports/'sports-verified-matchups.csv').open('w',newline='',encoding='utf-8') as f:
        w=csv.writer(f); w.writerow(['ProviderXMLTV_ID','XtreamChannelName','Status','VerifiedEvents']); w.writerows(audit)
    print('Xtream sports pre-publish verification:',len(replace),'live feeds;',sum(x[3] for x in audit),'confirmed events;',sum(x[2]=='NO GAME TODAY' for x in audit),'no-game feeds')
    return programmes


def apply_xtream_event_assignments(catalog, channels, programmes, reports):
    """Generate assigned event windows from dated Xtream names, excluding NCAAB."""
    now = datetime.now(timezone.utc)
    eastern = ZoneInfo('America/New_York')
    horizon = now + timedelta(days=2)
    month_lookup = {name: i for i, name in enumerate(
        ('JAN', 'FEB', 'MAR', 'APR', 'MAY', 'JUN', 'JUL', 'AUG', 'SEP', 'OCT', 'NOV', 'DEC'), 1)}
    assignments = defaultdict(list)
    for row in catalog:
        name = (row.get('ChannelName') or '').strip()
        pid = (row.get('EPGID') or '').strip()
        if not pid or pid not in channels:
            continue
        football = re.search(r'\bNCAAF\s*(?:GAME\s*)?0*(\d{1,2})\b', name, re.I)
        is_football = bool(football and 17 <= int(football.group(1)) <= 85)
        is_flo = bool(re.search(r'\b(?:FLOSPORTS|FLO\s*SPORTS|FLO\s*0*\d+)\b', name, re.I))
        is_espn = bool(re.search(r'\bESPN\s*(?:\+|PLUS)\b', name, re.I))
        # Numbered game feeds take their event assignment from the current
        # Xtream name, never from a generic league schedule or EPG donor.
        numbered = re.search(r'\b(NBA|NFL|MLS|MILB|MLB)\s*(?:GAME\s*)?0*(\d{1,2})\b', name, re.I)
        is_numbered = bool(numbered and (
            (numbered.group(1).upper() == 'NBA' and 1 <= int(numbered.group(2)) <= 15) or
            (numbered.group(1).upper() == 'NFL' and 1 <= int(numbered.group(2)) <= 16) or
            (numbered.group(1).upper() == 'MLS' and 1 <= int(numbered.group(2)) <= 34) or
            (numbered.group(1).upper() in ('MILB', 'MLB') and 1 <= int(numbered.group(2)) <= 70)))
        if not (is_football or is_flo or is_espn or is_numbered):
            continue
        if re.search(r'\bNCAAB\b', name, re.I):
            continue
        date_match = re.search(
            r'\b(JAN|FEB|MAR|APR|MAY|JUN|JUL|AUG|SEP|OCT|NOV|DEC)[A-Z]*\.?\s+(\d{1,2})(?:,?\s+(20\d{2}))?\b',
            name, re.I)
        time_match = re.search(r'\b(1[0-2]|0?[1-9]):([0-5]\d)\s*(AM|PM)\s*(ET|EST|EDT)\b', name, re.I)
        assignment = None
        if date_match and time_match:
            month = month_lookup[date_match.group(1).upper()]
            hour = int(time_match.group(1)) % 12 + (12 if time_match.group(3).upper() == 'PM' else 0)
            current_year = now.astimezone(eastern).year
            years = [int(date_match.group(3))] if date_match.group(3) else [current_year-1, current_year, current_year+1]
            candidates = []
            for year in years:
                try:
                    dt = datetime(year, month, int(date_match.group(2)), hour, int(time_match.group(2)), tzinfo=eastern)
                    candidates.append(dt.astimezone(timezone.utc))
                except ValueError:
                    continue
            if candidates:
                start = min(candidates, key=lambda dt: abs((dt-now).total_seconds()))
                specified_zone = time_match.group(4).upper()
                if specified_zone == 'ET' or start.astimezone(eastern).tzname() == specified_zone:
                    title = name.split(':', 1)[-1].split(date_match.group(0), 1)[0].strip(' -:|')
                    title = re.sub(r'^(?:LIVE|EVENT)\s*[-:|]\s*', '', title, flags=re.I).strip()
                    if title:
                        assignment = (title, start)
        assignments[pid].append((name, assignment))
    replacements = {}
    audit = []
    for pid, entries in assignments.items():
        parsed = [item[1] for item in entries]
        if not parsed or any(value is None or value != parsed[0] for value in parsed):
            audit.append((pid, 'UNVERIFIED', entries[0][0]))
            continue
        title, start = parsed[0]
        stop = start + timedelta(hours=4)
        local = start.astimezone(eastern)
        time_label = local.strftime('%I:%M %p').lstrip('0')
        event_label = f"{title} ({local.strftime('%B')} {local.day}, {time_label} {local.tzname()})"
        result = []
        if now < start:
            result.append(flo_programme(pid, f"Upcoming: {title} ({local.strftime('%A, %B')} {local.day}, {time_label} {local.tzname()})", now, start, 'Xtream event assignment.'))
        if start < horizon and stop > now:
            result.append(flo_programme(pid, event_label, max(start, now), min(stop, horizon), 'Xtream event assignment.'))
        if stop <= now:
            result.append(flo_programme(pid, 'Event has Concluded', now, horizon, 'Assigned event concluded.'))
        elif stop < horizon:
            result.append(flo_programme(pid, 'Event has Concluded', stop, horizon, 'Assigned event concluded.'))
        replacements[pid] = result
        audit.append((pid, 'ASSIGNED', entries[0][0]))
    if replacements:
        programmes = [p for p in programmes if p.get('channel') not in replacements]
        for result in replacements.values():
            programmes.extend(result)
    with (reports / 'xtream-event-assignments.csv').open('w', newline='', encoding='utf-8') as f:
        writer = csv.writer(f)
        writer.writerow(['XMLTV_ID', 'Status', 'ProviderChannelName'])
        writer.writerows(audit)
    print('Xtream event assignments:', len(replacements), 'channels; NCAAB excluded')
    return programmes


def main():
    try:
        fresh_catalog = refresh_playlist_catalog()
    except Exception as exc:
        # Do not print exception: urllib errors can contain server URL.
        print('Xtream refresh failed (' + type(exc).__name__ + '); using filtered M3U fallback')
        fresh_catalog = None
    catalog = fresh_catalog if fresh_catalog is not None else [r for r in rows(ROOT / 'channels.csv') if allowed_category(r.get('Group', ''))]
    if not catalog:
        raise RuntimeError('No channels in allowed categories; cannot build guide')
    print('Playlist catalog ready:', len(catalog), 'channels; now fetching guide sources')
    legacy = rows(ROOT / 'matches.csv')
    # MY_EPG_V2_APPROVED_OVERRIDE_2026: explicit StreamID-based mappings.
    # Approval with a blank EPGID is not a playable programme mapping.
    approved_by_streamid = {}
    approved_file = ROOT / 'approved_mappings.csv'
    if approved_file.is_file():
        for approved in rows(approved_file):
            streamid = (approved.get('StreamID') or '').strip()
            source = (approved.get('PreferredSource') or '').strip().lower()
            cid = (approved.get('EPGID') or '').strip()
            if source not in ('epg2', 'epg6', 'epg37') or not cid or not streamid:
                continue
            pair = (source, cid)
            prior = approved_by_streamid.get(streamid)
            if prior is not None and prior != pair:
                raise RuntimeError('Conflicting approved mappings for StreamID ' + streamid)
            approved_by_streamid[streamid] = pair
        print('Explicit approved StreamID mappings loaded:', len(approved_by_streamid))
    else:
        print('No approved_mappings.csv present; retaining legacy matching only')
    site = ROOT / 'site'
    site.mkdir(exist_ok=True)
    reports = ROOT / 'reports'
    reports.mkdir(exist_ok=True)

    # First index source channel IDs and display names. No fuzzy guesses.
    source_channels = {}
    source_data = {}
    by_name = defaultdict(set)
    by_alias = defaultdict(set)
    for source, url in SOURCES.items():
        print('Reading', source, flush=True)
        raw = load_guide(source, url)
        if raw is None:
            continue
        source_data[source] = raw
        with io.BytesIO(raw) as buf:
            for _, elem in ET.iterparse(buf, events=('end',)):
                if elem.tag.rsplit('}', 1)[-1] == 'channel':
                    cid = elem.get('id', '')
                    if cid:
                        source_channels[(source, cid)] = clone(elem)
                        by_name[clean_name(cid)].add((source, cid))
                        for alias in canonical_names(cid):
                            by_alias[alias].add((source, cid))
                        for d in elem.findall('display-name'):
                            if d.text and len(clean_name(d.text)) >= 5:
                                by_name[clean_name(d.text)].add((source, cid))
                                for alias in canonical_names(d.text):
                                    by_alias[alias].add((source, cid))
                    elem.clear()
                elif elem.tag.rsplit('}', 1)[-1] == 'programme':
                    elem.clear()
                # IMPORTANT: do not clear display-name/icon child nodes before
                # their parent channel is indexed.
    if not source_data:
        raise RuntimeError('Neither EPG2 nor EPG37 is accessible. Check EPG2_URL / EPG37_URL '
                           'or commit sources/epg2.xml.gz and sources/epg37.xml.gz. '
                           'No empty EPG will be published.')
    # The companion playlists disambiguate the XMLTV channel IDs, even when
    # XMLTV display-name values are abbreviated or contain an event title.
    companion_names = defaultdict(set)
    companion_aliases = defaultdict(set)
    companion_leagues = defaultdict(set)
    for source, cid, name, group in companion_entries():
        pair = (source, cid)
        if pair not in source_channels:
            continue
        for key in (clean_name(name), clean_name(re.sub(r'\s*[:|]\s*.*$', '', name))):
            if len(key) >= 5: companion_names[key].add(pair)
        for key in canonical_names(name): companion_aliases[key].add(pair)
        feed = league_feed(name)
        if feed: companion_leagues[feed].add(pair)
    # XMLTV itself may expose game-bearing numbered feed labels absent from M3U.
    for pair, ch in source_channels.items():
        for display in ch.findall('display-name'):
            feed = league_feed(display.text or '')
            if feed: companion_leagues[feed].add(pair)
    print('Companion source entries loaded:', sum(map(len, companion_names.values())))
    print('Source channel IDs:', len(source_channels))
    flo_index = flo_source_index(source_channels)
    print('Unique FLSP numbers in EPG2:', sum(len(v) == 1 for v in flo_index.values()))
    espn_index = espn37_numbered_index(source_channels)
    print('Unique ESPN+ numbers in EPG37:', sum(len(v) == 1 for v in espn_index.values()))
    by_source_id = defaultdict(set)
    for pair in source_channels:
        by_source_id[pair[1].casefold()].add(pair)

    # Preserve verified mappings by original playlist tvg-id, and by exact channel name.
    legacy_by_id = defaultdict(set)
    legacy_by_name = defaultdict(set)
    for r in legacy:
        pair = (source_key(r.get('source')), r.get('source_channel_id', ''))
        if pair not in source_channels:
            continue
        if r.get('original_tvg_id'):
            legacy_by_id[r['original_tvg_id'].casefold()].add(pair)
        if r.get('playlist_channel'):
            legacy_by_name[clean_name(r['playlist_channel'])].add(pair)

    # One output XMLTV channel per distinct provider EPG ID; legacy original IDs retained.
    requested = defaultdict(set)
    audit = []
    flo_provider_names = {}
    for r in catalog:
        name = r.get('ChannelName', '')
        epgid = (r.get('EPGID') or '').strip()
        key = clean_name(name)
        tvg_name = clean_name(r.get('TVGName', ''))
        if not key or name.strip().startswith('#####'):
            continue
        candidates = set()
        method = ''
        flo_num = flo_number(name) if re.search(r'FLO\s*SPORTS', r.get('Group',''), re.I) else None
        espn_num = event_number(name, r'ESPN\s*\+|ESPN\s*PLUS|ESPNPLUS') if re.search(r'ESPN\s*\+|ESPN\s*PLUS', (r.get('Group','') + ' ' + name), re.I) else None
        flo_pair = None
        if flo_num is not None and len(flo_index.get(flo_num, ())) == 1:
            flo_pair = next(iter(flo_index[flo_num]))
        if epgid:
            candidates = legacy_by_id.get(epgid.casefold(), set())
            method = 'verified mapping by provider ID'
            if len(candidates) != 1:
                candidates = by_source_id.get(epgid.casefold(), set())
                method = 'exact source ID'
        if len(candidates) != 1:
            candidates = legacy_by_name.get(key, set())
            method = 'verified mapping by channel name'
        if len(candidates) != 1 and tvg_name and len(tvg_name) >= 5:
            tvg_candidates = by_name.get(tvg_name, set())
            if len(tvg_candidates) == 1:
                candidates = tvg_candidates
                method = 'exact normalized TVG name'
        if len(candidates) != 1 and len(key) >= 5:
            name_candidates = by_name.get(key, set())
            if len(name_candidates) == 1 or not candidates:
                candidates = name_candidates
                method = 'exact normalized source name'
        if len(candidates) != 1:
            aliases = canonical_names(name) | canonical_names(r.get('TVGName', ''))
            alias_matches = set().union(*(by_alias.get(k, set()) for k in aliases)) if aliases else set()
            alias_matches = select_unique(alias_matches)
            if len(alias_matches) == 1:
                candidates = alias_matches
                method = 'exact conservative source alias'
        # Prefer a verified exact source-playlist name before weaker aliases.
        # Never replace a unique provider-ID mapping with an unrelated name.
        if len(candidates) != 1:
            opts = companion_names.get(key, set())
            if tvg_name: opts = opts | companion_names.get(tvg_name, set())
            selected = choose_companion(opts, epgid)
            if len(selected) == 1:
                candidates = selected
                method = 'exact companion M3U channel name'
        if len(candidates) != 1:
            aliases = canonical_names(name) | canonical_names(r.get('TVGName', ''))
            opts = set().union(*(companion_aliases.get(k,set()) for k in aliases)) if aliases else set()
            selected = choose_companion(opts, epgid)
            if len(selected) == 1:
                candidates = selected
                method = 'conservative companion M3U alias'
        if len(candidates) != 1:
            feed = league_feed(name)
            if feed:
                league, number, region = feed
                opts = companion_leagues.get(feed, set())
                if not region:
                    opts = set().union(*(companion_leagues.get((league,number,rg),set()) for rg in ('','US','CA')))
                selected = choose_companion(opts, epgid, source_channels, sports=True)
                if len(selected) == 1:
                    candidates = selected
                    method = 'league and numbered feed via companion M3U'
        # Re-evaluate numbered league feeds when the earlier match is only a
        # name/alias candidate. Preserve verified provider-ID and legacy IDs.
        feed = league_feed(name)
        if feed and method not in ('verified mapping by provider ID', 'exact source ID'):
            league, number, region = feed
            opts = set(companion_leagues.get(feed, set()))
            if not region:
                opts.update(companion_leagues.get((league, number, 'US'), set()))
                opts.update(companion_leagues.get((league, number, 'CA'), set()))
            selected = choose_companion(opts, epgid, source_channels, sports=True)
            if len(selected) == 1:
                candidates = selected
                method = 'numbered sports feed matched by league and number'
        # Numbered sports: override generic verified mappings ONLY when a
        # source feed with the same league and number advertises a real event.
        # Keep the provider's XMLTV output ID; only change its source pairing.
        feed = league_feed(name)
        if feed and flo_num is None and espn_num is None:
            league, number, region = feed
            opts = set(companion_leagues.get(feed, set()))
            if region:
                opts.update(companion_leagues.get((league, number, ''), set()))
            else:
                for rg in ('US', 'CA'):
                    opts.update(companion_leagues.get((league, number, rg), set()))
            ranked = [(sports_source_quality(p, source_channels), p) for p in opts]
            ranked.sort(reverse=True)
            current_score = max((sports_source_quality(p, source_channels) for p in candidates), default=-1)
            if ranked and ranked[0][0] >= 10 and ranked[0][0] > current_score:
                if len(ranked) == 1 or ranked[0][0] > ranked[1][0]:
                    candidates = {ranked[0][1]}
                    method = 'numbered sports: event-bearing source preferred'
        # Explicit numbered FloSports labels take priority over fuzzy event names.
        # Do not guess if the EPG2 FLSP number is duplicated.
        if flo_pair:
            candidates = {flo_pair}
            method = 'numbered FLO to EPG2 FLSP'
        elif flo_num is not None:
            candidates = flo_index.get(flo_num, set())
            method = 'FLSP number ambiguous' if candidates else 'FLSP number not found'
        if espn_num is not None and flo_num is None:
            # ESPN+ feeds must use EPG37, never a similarly named EPG2 feed.
            candidates = set(espn_index.get(espn_num, set()))
            method = 'numbered ESPN+ to EPG37' if len(candidates) == 1 else ('ESPN+ ambiguous in EPG37' if candidates else 'ESPN+ absent from EPG37')
        # Approved fixed-channel mappings take priority over name heuristics.
        # Preserve the provider's output EPGID; never replace it with source ID.
        # A source ID must actually exist in the loaded XMLTV file.
        approved_pair = approved_by_streamid.get((r.get('StreamID') or '').strip())
        if approved_pair is not None:
            if approved_pair in source_channels:
                candidates = {approved_pair}
                method = 'user-approved mapping by StreamID'
            else:
                print('WARNING approved source ID absent from XMLTV for StreamID',
                      (r.get('StreamID') or '').strip())
        candidates = select_unique(candidates)
        suggested_source = ''
        suggested_id = ''
        if len(candidates) == 1:
            pair = next(iter(candidates))
            suggested_source, suggested_id = pair
            if flo_num is not None and pair[0] == "epg2":
                flo_provider_names[epgid or ("matched." + pair[0] + "." + pair[1])] = name
            # Preserve all uniquely matched channels in the XMLTV, even if the
            # provider playlist has no tvg-id. This increases guide coverage;
            # a blank playlist tvg-id may still require manual TiviMate mapping.
            if epgid:
                requested[epgid].add(pair)
                status = 'candidate'
            else:
                status = 'matched but missing provider EPG ID'
                # Namespace to avoid collisions between EPG2 and EPG37 IDs.
                # Stable, per-stream XMLTV ID. A shared source channel ID must not
                # collapse distinct Xtream channels into one TiviMate guide entry.
                stream_id = (r.get('StreamID') or '').strip()
                generated_id = ('xtream.' + stream_id) if stream_id else ('matched.' + pair[0] + '.' + pair[1])
                requested[generated_id].add(pair)
        else:
            status = 'ambiguous' if candidates else 'unmatched'
            method = ''
        audit.append({'FloNumber': ('%03d' % flo_num) if flo_num is not None else '', 'ESPNNumber': ('%03d' % espn_num) if espn_num is not None else '', 'Group': r.get('Group',''), 'ChannelName': name,
                      'StreamID': r.get('StreamID',''), 'EPGID': epgid,
                      'Status': status, 'Method': method,
                      'SuggestedSource': suggested_source,
                      'SuggestedSourceID': suggested_id,
                      'NeedsPlaylistID': 'yes' if not epgid and len(candidates) == 1 else 'no'})

    # Existing verified IDs are always retained, even if absent from the new export.
    for original_id, pairs in legacy_by_id.items():
        if len(pairs) == 1:
            for r in legacy:
                if (r.get('original_tvg_id') or '').casefold() == original_id:
                    requested[r['original_tvg_id']].update(pairs)
                    break

    # Resolve conflicts without silently publishing a wrong schedule.
    chosen = {}
    for target, pairs in requested.items():
        if len(pairs) == 1:
            chosen[target] = next(iter(pairs))
    # Numbered sports: EPG2 and EPG37 may use different XMLTV IDs for the
    # SAME numbered feed. Publish the best schedule under BOTH source IDs,
    # while retaining existing provider and generated output IDs.
    # Never alias ESPN+ (EPG37 only) or FloSports (custom schedules).
    sports_aliases = defaultdict(set)
    for feed, pairs in companion_leagues.items():
        league, number, region = feed
        if not (1 <= number <= 999):
            continue
        for pair in pairs:
            sports_aliases[(league, number, region)].add(pair)

    # Add provider names to the alias index. They establish the exact feed
    # identity, even when a source XMLTV display name is generic.
    provider_sports = defaultdict(set)
    for row in audit:
        feed = league_feed(row['ChannelName'])
        if feed and row['SuggestedSource'] and row['SuggestedSourceID']:
            provider_sports[feed].add((row['SuggestedSource'], row['SuggestedSourceID']))
    for feed, pairs in provider_sports.items():
        sports_aliases[feed].update(pairs)

    # A source ID must identify only one numbered league feed; never reuse
    # it when the companion playlist labels it as a different game number.
    pair_feeds = defaultdict(set)
    for feed, pairs in sports_aliases.items():
        for pair in pairs:
            pair_feeds[pair].add(feed)

    sports_alias_count = 0
    for feed, pairs in sorted(sports_aliases.items()):
        league, number, region = feed
        eligible = {p for p in pairs if p in source_channels and
                    all(f[:2] == (league, number) for f in pair_feeds[p])}
        if not eligible:
            continue
        # Only cross-copy when region is unambiguous; CA and US must not be
        # collapsed into the same feed simply because numbers match.
        other_regions = {f[2] for p in eligible for f in pair_feeds[p] if f[2]}
        if region == '' and len(other_regions) > 1:
            continue
        ranked = sorted(eligible, key=lambda p: (sports_source_quality(p, source_channels),
                                                  p[0] == 'epg2', p[1]), reverse=True)
        best = ranked[0]
        if len(ranked) > 1 and sports_source_quality(ranked[0], source_channels) == sports_source_quality(ranked[1], source_channels):
            # Tie is acceptable only for a known already-selected source;
            # otherwise keep original mappings to avoid false assignments.
            already = [p for p in ranked if p in chosen.values()]
            if already:
                best = already[0]
        # Publish source IDs as XMLTV IDs so TiviMate can match either source.
        for pair in eligible:
            target = pair[1]
            if target in requested and any(p not in eligible for p in requested[target]):
                continue
            if target in chosen and chosen[target] not in eligible:
                continue
            if target not in chosen or sports_source_quality(best, source_channels) > sports_source_quality(chosen[target], source_channels):
                chosen[target] = best
                sports_alias_count += 1
        # Also upgrade existing provider IDs that resolve to this exact feed.
        for row in audit:
            if league_feed(row['ChannelName']) != feed:
                continue
            target = row['EPGID'] or (('xtream.' + row['StreamID']) if row['StreamID'] else ('matched.' + row['SuggestedSource'] + '.' + row['SuggestedSourceID']))
            if target in chosen and chosen[target] in eligible and sports_source_quality(best, source_channels) > sports_source_quality(chosen[target], source_channels):
                chosen[target] = best
    print('Numbered sports XMLTV ID aliases added/upgraded:', sports_alias_count)

    reverse = defaultdict(list)
    for target, pair in chosen.items():
        reverse[pair].append(target)
    print('Unambiguous output IDs:', len(chosen))

    channels = {}
    programmes = []
    cutoff = datetime.now(timezone.utc) - timedelta(hours=12)
    counts = Counter()
    flo_starts = defaultdict(list)
    # Collect current listings only, keeping memory bounded by selected channels.
    for source, raw in source_data.items():
        with io.BytesIO(raw) as buf:
            for _, elem in ET.iterparse(buf, events=('end',)):
                tag = elem.tag.rsplit('}', 1)[-1]
                if tag == 'programme':
                    cid = elem.get('channel', '')
                    targets = reverse.get((source, cid), ())
                    if targets and valid_time(elem.get('stop', ''), cutoff):
                        if source == "epg2":
                            start_dt = parse_xmltv_start(elem.get("start"))
                            if start_dt:
                                for target in targets:
                                    if target in flo_provider_names:
                                        flo_starts[target].append(start_dt)
                        for target in targets:
                            p = clone(elem)
                            p.set('channel', target)
                            programmes.append(p)
                            counts[target] += 1
                    elem.clear()
                elif tag == 'channel':
                    elem.clear()
                # IMPORTANT: do not clear title/desc children before cloning
                # their parent programme. Earlier builds lost every title.
    # WATE 6 fallback, when its old EPG37 mapping is stale.
    wate_ids = {r.get('original_tvg_id') for r in legacy
                if 'WATE' in (r.get('playlist_channel') or '').upper() and r.get('original_tvg_id')}
    if wate_ids and ('epg2', 'wate.us') in source_channels:
        for target in wate_ids:
            if not counts[target]:
                chosen[target] = ('epg2', 'wate.us')
                reverse[('epg2', 'wate.us')].append(target)
        # Fetch fallback programmes if needed.
        missing = [t for t in wate_ids if not counts[t]]
        if missing:
            raw = source_data['epg2']
            with io.BytesIO(raw) as buf:
                for _, elem in ET.iterparse(buf, events=('end',)):
                    if elem.tag.rsplit('}', 1)[-1] == 'programme' and elem.get('channel') == 'wate.us' and valid_time(elem.get('stop',''), cutoff):
                        for target in missing:
                            p = clone(elem); p.set('channel', target)
                            programmes.append(p); counts[target] += 1
                    elem.clear()

    # Never discard a verified match merely because its current source schedule
    # is empty. XMLTV permits channels without programme records.
    for target, pair in chosen.items():
        if pair in source_channels:
            ch = clone(source_channels[pair]); ch.set('id', target)
            channels[target] = ch
    # For WATE fallback, use the fallback source channel metadata.
    for target in wate_ids:
        if counts[target] and target not in channels and ('epg2','wate.us') in source_channels:
            ch = clone(source_channels[('epg2','wate.us')]); ch.set('id',target); channels[target] = ch
    # Retain existing provider IDs even when a current programme or source
    # mapping is unavailable. Do not invent programme titles for these.
    for r in catalog:
        epgid = (r.get('EPGID') or '').strip()
        if not epgid or epgid in channels:
            continue
        name = (r.get('ChannelName') or '').strip()
        if not name or name.startswith('#####'):
            continue
        ch = ET.Element('channel', {'id': epgid})
        ET.SubElement(ch, 'display-name').text = name
        channels[epgid] = ch

    # Rename every resolved FloSports guide channel to its provider FLO number.
    # This changes display names, not XMLTV IDs (which TiviMate uses for mapping).
    for row in audit:
        if row['FloNumber'] and row['SuggestedSource'] == 'epg2':
            target = row['EPGID'] or (('xtream.' + row['StreamID']) if row['StreamID'] else ('matched.' + row['SuggestedSource'] + '.' + row['SuggestedSourceID']))
            if target in channels:
                ch = channels[target]
                for label in list(ch.findall('display-name')):
                    ch.remove(label)
                ET.SubElement(ch, 'display-name', {'lang': 'en'}).text = 'FLO ' + row['FloNumber']

    # Replace FloSports schedules only. ESPN+ is intentionally unchanged.
    flo_custom = {}
    now_utc = datetime.now(timezone.utc)
    for target, provider_name in flo_provider_names.items():
        if target in channels:
            schedule = flo_custom_schedule(target, provider_name, flo_starts[target], now_utc)
            if schedule is None:
                # No advertised event with an ET start: never copy unrelated
                # EPG2 events into this provider feed.
                schedule = [flo_programme(target, 'No Event at This Time',
                                          now_utc, now_utc + timedelta(days=2),
                                          'No event is currently advertised for this FloSports channel.')]
            flo_custom[target] = schedule
    if flo_custom:
        programmes = [p for p in programmes if p.get("channel") not in flo_custom]
        for target, schedule in flo_custom.items():
            programmes.extend(schedule)
            counts[target] = len(schedule)
    print("FloSports provider event schedules:", len(flo_custom))
    programmes = [p for p in programmes if p.get('channel') in channels]

    # Sports-only repair: don't publish orphan/empty synthetic sports aliases.
    # Provider IDs remain available for channel assignment; genuine source IDs
    # are retained when they contain current, non-placeholder programmes.
    # No programme times or event titles are invented.
    sports_ids = set()
    provider_ids = {(r.get('EPGID') or '').strip() for r in catalog if (r.get('EPGID') or '').strip()}
    for cid, channel in channels.items():
        names = [el.text or '' for el in channel.findall('display-name')]
        if any(league_feed(name) for name in names) or league_feed(cid):
            sports_ids.add(cid)
    now_utc = datetime.now(timezone.utc)
    horizon = now_utc + timedelta(hours=48)
    by_programme = defaultdict(list)
    for p in programmes:
        by_programme[p.get('channel', '')].append(p)
    def genuine_future(p):
        start = parse_xmltv_start(p.get('start', ''))
        stop = parse_xmltv_start(p.get('stop', ''))
        if not start or not stop or stop <= now_utc or start >= horizon or stop <= start:
            return False
        title = ' '.join((el.text or '') for el in p.findall('title')).strip()
        return bool(title and not re.search(r'^(?:signing off|no event(?: at this time)?|no information|to be announced|tba|off air)$', title, re.I))
    # Sports provider-ID schedule rescue. Source XMLTV IDs sometimes carry a
    # usable schedule while the provider's original tvg-id remains empty.
    # Copy actual XMLTV programme elements only; never synthesize game times.
    # Require identical league/number and compatible regional identity.
    provider_sports_names = defaultdict(set)
    for r in catalog:
        pid = (r.get('EPGID') or '').strip()
        feed = league_feed(r.get('ChannelName', ''))
        if pid and feed:
            provider_sports_names[pid].add(feed)
    for cid, ch in channels.items():
        if cid in provider_sports_names:
            continue
        feeds = {league_feed(x.text or '') for x in ch.findall('display-name')}
        feeds.discard(None)
        if feeds and cid in provider_ids:
            provider_sports_names[cid].update(feeds)

    sports_schedule_rescue = []
    donor_feeds = defaultdict(set)
    for cid in sports_ids:
        if cid not in channels or not any(genuine_future(p) for p in by_programme[cid]):
            continue
        feeds = {league_feed(cid)}
        feeds.update(league_feed(x.text or '') for x in channels[cid].findall('display-name'))
        feeds.discard(None)
        if len({(f[0], f[1]) for f in feeds}) != 1:
            continue
        for feed in feeds:
            donor_feeds[feed].add(cid)

    for target, target_feeds in sorted(provider_sports_names.items()):
        if target not in channels or len(target_feeds) != 1:
            continue
        if any(genuine_future(p) for p in by_programme[target]):
            continue
        league, number, region = next(iter(target_feeds))
        candidate_ids = set(donor_feeds.get((league, number, region), set()))
        if region:
            candidate_ids.update(donor_feeds.get((league, number, ''), set()))
        else:
            candidate_ids.update(donor_feeds.get((league, number, 'US'), set()))
            candidate_ids.update(donor_feeds.get((league, number, 'CA'), set()))
        safe_donors = []
        for donor in candidate_ids - {target}:
            # Refuse ambiguous cross-region mappings (US versus CA).
            labels = {league_feed(donor)}
            labels.update(league_feed(x.text or '') for x in channels[donor].findall('display-name'))
            labels.discard(None)
            if len({(f[0], f[1]) for f in labels}) != 1:
                continue
            regions = {f[2] for f in labels if f[2]}
            if region and any(r != region for r in regions):
                continue
            if not region and len(regions) > 1:
                continue
            upcoming = [p for p in by_programme[donor] if genuine_future(p)]
            if upcoming:
                safe_donors.append((donor, upcoming, regions))
        if not safe_donors:
            sports_schedule_rescue.append((target, league, number, region, '', 0, 'NO_VERIFIED_DONOR'))
            continue
        # If unregionalized provider ID has competing regional sources, do
        # not arbitrarily choose one regional schedule.
        if not region and len({r for _, _, rs in safe_donors for r in rs}) > 1:
            sports_schedule_rescue.append((target, league, number, region, '', 0, 'AMBIGUOUS_REGION'))
            continue
        # Choose donor with most genuine upcoming records, preferring a
        # previously selected source mapping when counts tie.
        safe_donors.sort(key=lambda item: (len(item[1]),
                          chosen.get(target) == chosen.get(item[0]) and chosen.get(target) is not None,
                          item[0] == (chosen.get(target) or ('', ''))[1], item[0]), reverse=True)
        donor, usable, _ = safe_donors[0]
        # Replace stale/placeholder entries only for the original provider ID.
        programmes = [p for p in programmes if p.get('channel') != target]
        copies = []
        for p in by_programme[donor]:
            if genuine_future(p):
                copy = clone(p)
                copy.set('channel', target)
                copies.append(copy)
        programmes.extend(copies)
        by_programme[target] = copies
        counts[target] = len(copies)
        sports_schedule_rescue.append((target, league, number, region, donor, len(copies), 'COPIED_VERIFIED_LISTINGS'))
    print('Sports provider ID schedule rescue:',
          sum(r[-1] == 'COPIED_VERIFIED_LISTINGS' for r in sports_schedule_rescue), 'IDs repaired')

    removed_aliases = set()
    for cid in sports_ids:
        # Keep provider IDs even when schedules are empty: deleting them would
        # break the provider's original tvg-id mapping in TiviMate.
        if cid not in provider_ids and not any(genuine_future(p) for p in by_programme[cid]):
            removed_aliases.add(cid)
    for cid in removed_aliases:
        channels.pop(cid, None)
    if removed_aliases:
        programmes = [p for p in programmes if p.get('channel') not in removed_aliases]
    # Limit repeated sports guide choices to two XMLTV channel IDs per
    # exact primary display name. Prioritize provider IDs and usable listings.
    # Distinct game numbers remain distinct: NFL | 01 != NFL | 02.
    # Only league_feed()-recognized sports are affected.
    sports_duplicate_removed = []
    sports_by_name = defaultdict(list)
    for cid in sorted(sports_ids - removed_aliases):
        channel = channels.get(cid)
        if channel is None:
            continue
        labels = [(x.text or '').strip() for x in channel.findall('display-name')]
        if not labels:
            continue
        # Use the primary label only. Other source aliases must not merge
        # unrelated channels into the same group.
        key = re.sub(r'\s+', ' ', labels[0]).casefold().strip()
        if key:
            sports_by_name[key].append(cid)
    for key, ids in sports_by_name.items():
        if len(ids) <= 2:
            continue
        def sports_rank(cid):
            upcoming = sum(genuine_future(p) for p in by_programme[cid])
            return (cid in provider_ids, upcoming > 0, upcoming,
                    len(by_programme[cid]), not cid.startswith('matched.'), cid)
        ranked = sorted(ids, key=sports_rank, reverse=True)
        kept = ranked[:2]
        for cid in ranked[2:]:
            sports_duplicate_removed.append((cid, channels[cid].findtext('display-name', ''),
                                              ' | '.join(kept),
                                              'YES' if cid in provider_ids else 'NO'))
            removed_aliases.add(cid)
            channels.pop(cid, None)
    if sports_duplicate_removed:
        programmes = [p for p in programmes if p.get('channel') not in removed_aliases]
    # Existing coverage report includes both removals and kept entries.
    sports_coverage = []
    for cid in sorted(sports_ids):
        if cid in removed_aliases:
            status = 'REMOVED_DUPLICATE' if any(x[0] == cid for x in sports_duplicate_removed) else 'REMOVED_EMPTY_ALIAS'
        elif any(genuine_future(p) for p in by_programme[cid]):
            status = 'HAS_UPCOMING_EVENT'
        elif by_programme[cid]:
            status = 'NO_UPCOMING_EVENT_OR_PLACEHOLDER_ONLY'
        else:
            status = 'NO_PROGRAMMES'
        names = [el.text or '' for el in channels[cid].findall('display-name')] if cid in channels else []
        sports_coverage.append((cid, ' | '.join(names), status, len(by_programme[cid]),
                                sum(genuine_future(p) for p in by_programme[cid]),
                                'YES' if cid in provider_ids else 'NO'))
    print('Sports-only validation: ', len(sports_ids), 'sports IDs;', len(removed_aliases), 'empty synthetic aliases removed')
    # Complete Xtream sports verification before the XMLTV file is created.
    programmes = make_sports_guide(catalog, channels, programmes, reports)
    programmes = apply_xtream_event_assignments(catalog, channels, programmes, reports)
    # Live sports channel-name refresh, using EPG2/EPG37 already downloaded by
    # this same GitHub Actions build. Never changes XMLTV IDs or stream IDs.
    from sports_channel_names import run as refresh_sports_names
    refresh_sports_names(catalog, channels, programmes, source_channels,
                         source_data, chosen, reports)
    if not channels or not programmes:
        raise RuntimeError('No current programme data found: refusing to publish empty guide')

    for row in audit:
        if row['FloNumber'] and row['SuggestedSource'] == 'epg2':
            cid = row['SuggestedSourceID']
            row['EventStatus'] = ('Scheduled Event' if flo_advertised(row['ChannelName']) else 'No Event at This Time')
        elif row['FloNumber']:
            row['EventStatus'] = 'Unmatched'
        else:
            row['EventStatus'] = ''
    with (reports / 'flosports-status.csv').open('w', newline='', encoding='utf-8') as f:
        fields = ['FloNumber','Group','ChannelName','StreamID','EPGID','SuggestedSourceID','EventStatus','NeedsPlaylistID']
        w = csv.DictWriter(f, fieldnames=fields)
        w.writeheader()
        w.writerows({k: row.get(k, '') for k in fields} for row in audit if row['FloNumber'])
    with (reports / 'missing-id-suggestions.csv').open('w', newline='', encoding='utf-8') as f:
        fields = ['Group', 'ChannelName', 'StreamID', 'SuggestedSource', 'SuggestedSourceID']
        writer = csv.DictWriter(f, fieldnames=fields)
        writer.writeheader()
        for row in audit:
            if row['Status'] == 'matched but missing provider EPG ID':
                writer.writerow({field: row.get(field, '') for field in fields})
    # TiviMate assigns XMLTV by Xtream epg_channel_id, not by stream_id or
    # channel display name. Report missing and conflicting provider IDs clearly.
    provider_id_to_streams = defaultdict(set)
    for item in catalog:
        pid = (item.get('EPGID') or '').strip()
        sid = (item.get('StreamID') or '').strip()
        if pid and sid:
            provider_id_to_streams[pid].add(sid)
    with (reports / 'tivimate-id-audit.csv').open('w', newline='', encoding='utf-8') as f:
        fields = ['Group', 'ChannelName', 'StreamID', 'XtreamEPGID', 'OutputXMLTV_ID', 'Status', 'Source', 'SourceChannelID']
        w = csv.DictWriter(f, fieldnames=fields)
        w.writeheader()
        for item in audit:
            pid = (item.get('EPGID') or '').strip()
            sid = (item.get('StreamID') or '').strip()
            output_id = pid or (('xtream.' + sid) if sid else '')
            if not pid:
                status = 'MISSING_XTREAM_EPG_ID_REQUIRES_PLAYLIST_ASSIGNMENT'
            elif len(provider_id_to_streams[pid]) > 1:
                status = 'SHARED_XTREAM_EPG_ID_CHECK_CHANNELS'
            elif output_id not in channels:
                status = 'ID_NOT_PUBLISHED'
            elif not any(p.get('channel') == output_id for p in programmes):
                status = 'ID_PRESENT_NO_PROGRAMMES'
            else:
                status = 'ID_MATCHES_GUIDE'
            w.writerow({'Group': item.get('Group', ''), 'ChannelName': item.get('ChannelName', ''),
                        'StreamID': sid, 'XtreamEPGID': pid, 'OutputXMLTV_ID': output_id,
                        'Status': status, 'Source': item.get('SuggestedSource', ''),
                        'SourceChannelID': item.get('SuggestedSourceID', '')})
    print('TiviMate ID audit created; missing Xtream EPG IDs cannot be fixed by XMLTV alone')
    with (reports / 'matching-report.csv').open('w', newline='', encoding='utf-8') as f:
        writer = csv.DictWriter(f, fieldnames=['FloNumber','ESPNNumber','Group','ChannelName','StreamID','EPGID','Status','Method','SuggestedSource','SuggestedSourceID','NeedsPlaylistID','EventStatus'])
        writer.writeheader(); writer.writerows(audit)
    with (reports / 'coverage.csv').open('w', newline='', encoding='utf-8') as f:
        w = csv.writer(f); w.writerow(['EPGID','Source','SourceChannelID','Programmes'])
        for target, pair in sorted(chosen.items()):
            w.writerow([target, *pair, counts[target]])
    with (reports / 'sports-coverage.csv').open('w', newline='', encoding='utf-8') as f:
        w = csv.writer(f)
        w.writerow(['XMLTV_ID', 'ChannelName', 'Status', 'ProgrammeCount', 'UpcomingEventCount48h', 'ProviderID'])
        w.writerows(sports_coverage)
    with (reports / 'sports-removed-aliases.csv').open('w', newline='', encoding='utf-8') as f:
        w = csv.writer(f)
        w.writerow(['XMLTV_ID', 'Reason'])
        w.writerows((cid, 'Exceeded two entries for the same sports channel' if any(x[0] == cid for x in sports_duplicate_removed) else 'No upcoming non-placeholder programme; synthetic ID') for cid in sorted(removed_aliases))
    with (reports / 'sports-provider-id-rescue.csv').open('w', newline='', encoding='utf-8') as f:
        w = csv.writer(f)
        w.writerow(['ProviderXMLTV_ID', 'League', 'FeedNumber', 'Region', 'DonorXMLTV_ID', 'CopiedProgrammes', 'Status'])
        w.writerows(sports_schedule_rescue)
    with (reports / 'sports-duplicate-limit.csv').open('w', newline='', encoding='utf-8') as f:
        w = csv.writer(f)
        w.writerow(['RemovedXMLTV_ID', 'ChannelName', 'KeptXMLTV_IDs', 'WasProviderID'])
        w.writerows(sports_duplicate_removed)
    print('Sports duplicate limit: removed', len(sports_duplicate_removed), 'extra IDs')
    out = site / 'epg.xml.gz' 
    with gzip.open(out, 'wb', compresslevel=6) as f:
        f.write(b'<?xml version="1.0" encoding="utf-8"?>\n<tv generator-info-name="My-EPG-v2-Expanded">\n')
        for ch in channels.values():
            f.write(ET.tostring(ch, encoding='utf-8')); f.write(b'\n')
        for p in programmes:
            f.write(ET.tostring(p, encoding='utf-8')); f.write(b'\n')
        f.write(b'</tv>\n')
    (site / '.nojekyll').touch()
    (site / 'index.html').write_text('<!doctype html><html><meta charset="utf-8"><title>My EPG</title><h1>My EPG</h1><p><a href="epg.xml.gz">Download guide</a></p></html>', encoding='utf-8')
    print('Published', len(channels), 'channels;', len(programmes), 'programmes')
    print('Matching report:', reports / 'matching-report.csv')
    print('Missing-ID suggestions:', reports / 'missing-id-suggestions.csv')

if __name__ == '__main__':
    main()
